    float g = dot(src, vec3(0.299, 0.587, 0.114));
    float M = pow(2.0, floor(coarse + 0.5));
    float K = floor(g * (16.0 / M) + 0.5) * M;
    vec2 dpx = floor(uv * iResolution.xy);
