        K = ign(dpx) <= K / calm ? calm : 0.0;
    }
    // The phase comes from the blue-noise mask, tiled. A phase from ign lines
    // the lit pixels of one frame up along diagonals.
    vec2 mt = (floor(mod(dpx, bluenoise_size)) + 0.5) / bluenoise_size;
